<template>
  <view class="netops-page">
    <view class="filter-card">
      <view class="filter-row">
        <picker mode="date" :value="filters.date" @change="filters.date = $event.detail.value; reload()"><view class="filter-chip">{{ filters.date }}⌄</view></picker>
        <picker :range="qualityOptions" range-key="label" @change="onQualityChange"><view class="filter-chip">{{ qualityLabel(filters.quality_code) }}⌄</view></picker>
        <view class="filter-chip olt-filter" @tap="oltPickerVisible = true">{{ selectedOltLabel }}⌄</view>
      </view>
      <view class="search-bar inner-search"><input v-model="filters.keyword" class="search-input" placeholder="MAC、OLT、用户、地址" confirm-type="search" @confirm="reload" /><button class="search-button" @tap="reload">筛选</button></view>
      <view class="filter-actions"><text>可按日期、原因和 OLT 定位异常</text><text @tap="exportReport">导出 Excel</text></view>
    </view>

    <view class="summary-grid"><MetricCard label="质差总数" :value="total" :hint="filters.date" tone="orange" /><MetricCard label="涉及 OLT" :value="stats.involved_olt || '--'" :hint="`较前日 ${deltaText}`" /><MetricCard label="光功率过低" :value="stats.rx_low || 0" tone="red" /><MetricCard label="光功率过高" :value="stats.rx_high || 0" tone="purple" /></view>
    <view v-if="summaryLoading" class="summary-loading"><view class="loading-dot" /></view>

    <view class="view-tabs"><view v-for="mode in viewModes" :key="mode.value" class="view-tab" :class="{ active: viewMode === mode.value }" @tap="viewMode = mode.value">{{ mode.label }}</view></view>
    <view v-if="viewMode === 'trend'" class="section-card">
      <view class="section-head"><view class="section-head-title">质差趋势</view><view class="section-head-meta">近 {{ trend.length }} 天</view></view>
      <scroll-view v-if="trend.length" scroll-x class="trend-scroll" :show-scrollbar="false"><view class="trend-chart"><view v-for="point in trend" :key="point.stat_date" class="trend-column"><view class="trend-count">{{ compactNumber(point.bad_count) }}</view><view class="trend-track"><view class="trend-stack" :style="{ height: trendHeight(point.bad_count) }"><view v-if="Number(point.rx_high || 0)" class="trend-segment high" :style="{ height: trendPart(point.rx_high, point.bad_count) }" /><view class="trend-segment low" :style="{ height: trendPart(point.rx_low, point.bad_count) }" /></view></view><view class="trend-date">{{ shortDate(point.stat_date) }}</view></view></view></scroll-view>
      <view v-if="trend.length" class="trend-legend"><text><i class="legend-dot low" />光功率过低</text><text><i class="legend-dot high" />光功率过高</text></view>
      <view v-else-if="summaryLoading" class="chart-skeleton"><view class="loading-dot" /></view><EmptyState v-else mark="势" title="暂无趋势数据" description="当前权限范围内还没有连续质差统计。" />
    </view>
    <view v-else-if="viewMode === 'stats'" class="stats-stack">
      <view class="section-card"><view class="section-head"><view class="section-head-title">OLT 质差排行</view><view class="section-head-meta">前 {{ Math.min(topOltLimit, topOlts.length) }} / {{ topOlts.length }} 台</view></view><view v-if="topOlts.length" class="rank-list"><view v-for="(item,index) in visibleTopOlts" :key="item.olt_device_id" class="rank-row"><view class="rank-index">{{ index + 1 }}</view><view class="rank-main"><view class="rank-name">{{ item.olt_name || `OLT ${item.olt_device_id}` }}</view><view class="rank-metrics"><text><b>{{ item.bad_count || 0 }}</b> 质差</text><text>{{ item.rx_low || 0 }} 低光</text><text>{{ item.rx_high || 0 }} 高光</text><text>{{ power(item.worst_rx) }}</text></view></view></view><view v-if="topOltLimit < topOlts.length" class="stats-more" @tap="topOltLimit += 10">再显示 10 台</view><view v-else-if="topOlts.length > 10" class="stats-more" @tap="topOltLimit = 10">收起</view></view><EmptyState v-else mark="OLT" title="暂无 OLT 质差统计" /></view>
      <view class="section-card"><view class="section-head"><view class="section-head-title">端口异常聚合</view><view class="section-head-meta">前 {{ Math.min(portLimit, portGroups.length) }} / {{ portGroups.length }} 个</view></view><view v-if="portGroups.length" class="rank-list"><view v-for="(item,index) in visiblePortGroups" :key="`${item.olt_device_id}-${item.pon_port}`" class="rank-row"><view class="rank-index port">{{ index + 1 }}</view><view class="rank-main"><view class="rank-name">{{ item.olt_name || `OLT ${item.olt_device_id}` }} · PON {{ item.pon_port }}</view><view class="rank-metrics"><text><b>{{ item.bad_count || 0 }}</b> 异常</text><text>{{ item.total_onu || 0 }} ONU</text><text>{{ badRate(item) }}</text><text>{{ power(item.worst_rx) }}</text></view></view></view><view v-if="portLimit < portGroups.length" class="stats-more" @tap="portLimit += 10">再显示 10 个端口</view><view v-else-if="portGroups.length > 10" class="stats-more" @tap="portLimit = 10">收起</view></view><view v-else-if="summaryLoading" class="chart-skeleton"><view class="loading-dot" /></view><EmptyState v-else mark="端" title="暂无端口质差统计" description="未识别端口默认不计入汇总。" /></view>
    </view>
    <view v-else class="section-card"><view class="section-head"><view class="section-head-title">质差明细</view><view class="section-head-meta">共 {{ total }} 条</view></view><view v-if="items.length" class="quality-list"><view v-for="item in items" :key="`${item.olt_device_id}-${item.onu_mac}-${item.if_index}`" class="quality-item" @tap="openOnu(item)"><view class="quality-top"><view class="mac">{{ item.display_mac || formatMac(item.onu_mac) }}</view><StatusBadge value="warning" :text="item.quality_label || qualityLabel(item.quality_code)" /></view><view class="quality-main"><view class="device-name">{{ item.olt_name || '--' }}</view><view class="power" :class="{ severe: Number(item.rx_power) < -28 }">RX {{ power(item.rx_power) }}</view></view><view class="quality-meta">{{ item.room_group || item.region || '--' }} / {{ item.room || '--' }} · PON {{ item.pon_port || '--' }}</view><view v-if="item.customer_name || item.gdf_account" class="customer-line">{{ item.customer_name || '未知用户' }} · {{ item.gdf_account || '--' }}</view><view class="time">{{ item.query_time || '--' }}</view></view></view><view v-else-if="loading" class="status-text">正在加载质差明细…</view><EmptyState v-else mark="空" title="没有质差记录" description="当前筛选条件下未发现光功率异常 ONU。" /><view v-if="items.length && items.length < total" class="load-more" @tap="loadMore">{{ loading ? '加载中…' : '继续加载' }}</view></view>
    <view v-if="oltPickerVisible" class="olt-mask" @tap="oltPickerVisible = false" @touchmove.stop><view class="olt-sheet" @tap.stop @touchmove.stop><view class="olt-sheet-head"><text>按区域、机房选择 OLT</text><text @tap="oltPickerVisible = false">取消</text></view><view class="olt-columns"><scroll-view scroll-y enhanced class="olt-column" :show-scrollbar="false"><view v-for="item in regions" :key="item" :class="{active: selectedRegion === item}" @tap="chooseRegion(item)">{{ regionLabel(item) }}</view></scroll-view><scroll-view scroll-y enhanced class="olt-column" :show-scrollbar="false"><view v-for="item in rooms" :key="item" :class="{active: selectedRoom === item}" @tap="chooseRoom(item)">{{ item }}</view></scroll-view><scroll-view scroll-y enhanced class="olt-column" :show-scrollbar="false"><view :class="{active: !filters.olt_device_ids}" @tap="chooseAllOlt">全部 OLT</view><view v-for="item in filteredOlts" :key="item.olt_device_id" :class="{active: String(filters.olt_device_ids) === String(item.olt_device_id)}" @tap="selectOlt(item)">{{ item.name || `OLT ${item.olt_device_id}` }}</view></scroll-view></view></view></view>
  </view>
</template>

<script setup>
import { computed, reactive, ref } from 'vue'
import { onLoad, onReachBottom } from '@dcloudio/uni-app'
import EmptyState from '../../../components/netops/EmptyState.vue'
import MetricCard from '../../../components/netops/MetricCard.vue'
import StatusBadge from '../../../components/netops/StatusBadge.vue'
import { downloadOnuQuality, getOltDeviceOptions, getOnuQuality } from '../../../api/netops'
import { messageLabel } from '../../../utils/labels'

const qualityOptions = [{ label: '全部原因', value: '' }, { label: '光功率过低', value: 'rx_low' }, { label: '光功率过高', value: 'rx_high' }, { label: '光功率缺失', value: 'rx_missing' }]
const regionLabels = { chengbei: '城北', chengdong: '城东', chengnan: '城南', chengxi: '城西', gaochun: '高淳', jiangning: '江宁', lishui: '溧水', liuhe: '六合', pukou: '浦口', qixia: '栖霞' }
const filters = reactive({ date: localDate(), keyword: '', quality_code: '', olt_device_ids: '' })
const viewModes = [{ label: '质差明细', value: 'detail' }, { label: '趋势', value: 'trend' }, { label: '统计表', value: 'stats' }]
const viewMode = ref('detail'); const items = ref([]); const stats = ref({}); const trend = ref([]); const topOlts = ref([]); const portGroups = ref([]); const total = ref(0); const page = ref(1); const loading = ref(false); const summaryLoading = ref(false); const oltPickerVisible = ref(false); const oltOptions = ref([]); const selectedRegion = ref('全部区域'); const selectedRoom = ref('全部机房'); const topOltLimit = ref(10); const portLimit = ref(10); const size = 30
const deltaText = computed(() => { const value = Number(stats.value.total_delta || 0); return value > 0 ? `+${value}` : String(value) })
const selectedOltLabel = computed(() => filters.olt_device_ids ? ((oltOptions.value.find((item) => String(item.olt_device_id) === String(filters.olt_device_ids)) || {}).name || '已选 OLT') : '全部 OLT')
const regions = computed(() => ['全部区域'].concat([...new Set(oltOptions.value.map((item) => item.region).filter(Boolean))]))
const rooms = computed(() => ['全部机房'].concat([...new Set(oltOptions.value.filter((item) => selectedRegion.value === '全部区域' || item.region === selectedRegion.value).map((item) => item.room || item.room_group).filter(Boolean))]))
const filteredOlts = computed(() => oltOptions.value.filter((item) => (selectedRegion.value === '全部区域' || item.region === selectedRegion.value) && (selectedRoom.value === '全部机房' || (item.room || item.room_group) === selectedRoom.value)))
const visibleTopOlts = computed(() => topOlts.value.slice(0, topOltLimit.value)); const visiblePortGroups = computed(() => portGroups.value.slice(0, portLimit.value))
onLoad(() => { loadOltOptions(); reload() }); onReachBottom(loadMore)
function reload() { page.value = 1; topOltLimit.value = 10; portLimit.value = 10; items.value = []; trend.value = []; topOlts.value = []; portGroups.value = []; loadData() }
function loadMore() { if (!loading.value && items.value.length < total.value) { page.value += 1; loadData(true) } }
function loadData(append = false) { loading.value = true; getOnuQuality({ ...filters, page: page.value, size, summary: 0, trend_days: 14 }).then((data) => { items.value = append ? items.value.concat(data.items || []) : (data.items || []); total.value = Number(data.total || 0); if (data.stats) stats.value = data.stats; if (page.value === 1) loadSummary() }).catch((error) => uni.showToast({ title: messageLabel(error.message), icon: 'none' })).finally(() => { loading.value = false }) }
function loadSummary() { summaryLoading.value = true; getOnuQuality({ ...filters, page: 1, size: 1, summary: 1, trend_days: 14 }).then((data) => { stats.value = data.stats || stats.value; trend.value = data.trend || []; topOlts.value = data.top_olts || []; portGroups.value = data.port_groups || [] }).catch((error) => uni.showToast({ title: messageLabel(error.message), icon: 'none' })).finally(() => { summaryLoading.value = false }) }
function loadOltOptions() { getOltDeviceOptions().then((data) => { oltOptions.value = data.items || [] }).catch(() => {}) }
function onQualityChange(event) { const item = qualityOptions[Number(event.detail.value)]; filters.quality_code = item ? item.value : ''; reload() }
function chooseRegion(value) { selectedRegion.value = value; selectedRoom.value = '全部机房' }; function chooseRoom(value) { selectedRoom.value = value }; function chooseAllOlt() { filters.olt_device_ids = ''; oltPickerVisible.value = false; reload() }; function selectOlt(item) { filters.olt_device_ids = String(item.olt_device_id); oltPickerVisible.value = false; reload() }
function regionLabel(value) { return regionLabels[value] || value }
function openOnu(item) { uni.navigateTo({ url: `/pages/netops/onu/index?type=mac&keyword=${encodeURIComponent(item.onu_mac || '')}` }) }
function exportReport() { uni.showLoading({ title: '正在导出' }); downloadOnuQuality(filters).then((filePath) => { uni.hideLoading(); uni.openDocument({ filePath, fileType: 'xlsx', showMenu: true }) }).catch((error) => { uni.hideLoading(); uni.showToast({ title: messageLabel(error.message), icon: 'none' }) }) }
function localDate() { const now = new Date(); const offset = now.getTimezoneOffset() * 60000; return new Date(now - offset).toISOString().slice(0, 10) }
function qualityLabel(value) { return ({ '': '全部原因', rx_low: '光功率过低', rx_high: '光功率过高', rx_missing: '光功率缺失' })[value] || value || '质差' }
function formatMac(value) { return String(value || '').replace(/(.{2})(?=.)/g, '$1:').toUpperCase() || '--' }; function power(value) { return value === null || value === undefined || value === '' ? '-- dBm' : `${value} dBm` }; function shortDate(value) { const text = String(value || ''); return text.length >= 10 ? text.slice(5, 10) : '--' }; function compactNumber(value) { const number = Number(value || 0); return number >= 10000 ? `${(number / 10000).toFixed(1)}万` : String(number) }; function trendHeight(value) { const max = Math.max(...trend.value.map((item) => Number(item.bad_count || 0)), 1); return `${Math.max(8, Number(value || 0) / max * 100)}%` }; function trendPart(value, totalValue) { const totalCount = Math.max(Number(totalValue || 0), 1); return `${Math.max(Number(value || 0) ? 2 : 0, Number(value || 0) / totalCount * 100)}%` }; function badRate(item) { const count = Number(item.total_onu || 0); return count ? `${(Number(item.bad_count || 0) / count * 100).toFixed(1)}%` : '--' }
</script>

